VIENTO = ("El viento llegó a la plaza / silbando una canción. / Las hojas, como mariposas, / bailaron alrededor. / Y el árbol, cansado, / se quedó quieto a escuchar.")

L(OA5, 5,
  "Este cuaderno, lápiz y el poema escrito en esta clase.",
  "Aprenderé a explicar con mis palabras qué quiere decir un poema completo, apoyándome en versos, comparaciones y personificaciones.",
  ["Reconozco comparaciones y personificaciones.", "Resumo cada estrofa."],
  ["Interpretar un poema significa decir qué creemos que quiere mostrar y por qué lo creemos. No basta con decir «me gustó». Hay que mostrar el verso que lo apoya.",
   "En el poema del viento, el viento silba una canción, las hojas bailan como mariposas y el árbol escucha. Una interpretación posible es: «El poema muestra un día de viento donde la naturaleza parece una fiesta». La evidencia es que el viento canta, las hojas bailan y el árbol escucha.",
   "Una interpretación completa tiene tres partes: lo que creo, el verso que lo apoya y la explicación de por qué ese verso lo muestra. Otra persona puede interpretar distinto, pero siempre debe apoyarse en el poema."],
  [("interpretación", "explicación de lo que quiere mostrar un poema"), ("evidencia", "verso o palabra del poema que apoya la interpretación"), ("naturaleza", "plantas, animales, viento, agua y todo lo que no hizo el ser humano"), ("fundamentar", "dar razones para apoyar una idea")],
  [("Interpretar con evidencia", f"Lee: «{VIENTO}» ¿Qué muestra el poema y qué verso lo apoya?", ["Pienso: el viento canta, las hojas bailan, el árbol escucha.", "Parece una fiesta en la plaza.", "Evidencia: «Las hojas, como mariposas, bailaron alrededor»."], "Muestra un día de viento como una fiesta; evidencia: las hojas bailaron"),
   ("Reconocer las figuras", "¿Qué comparación y qué personificación hay en el poema?", ["Comparación: «como mariposas».", "Personificación: el viento silba una canción.", "Las dos ayudan a imaginar la escena."], "Comparación: hojas como mariposas; personificación: el viento silba una canción")],
  [("Decir «el poema habla del viento» sin más explicación.", "Es una descripción y no una interpretación.", "Explica qué quiere mostrar y con qué verso."), ("Interpretar sin citar ningún verso.", "Se olvida la evidencia.", "Siempre copia el verso que te hizo pensar eso.")],
  ([E(f"Lee: «{VIENTO}» ¿Qué hizo el viento al llegar a la plaza?", "Silbó una canción", "El segundo verso lo dice."),
    E(f"Lee: «{VIENTO}» ¿Con qué se comparan las hojas?", "Con mariposas", "El tercer verso dice «como mariposas»."),
    E(f"Lee: «{VIENTO}» ¿Qué hizo el árbol al final?", "Se quedó quieto a escuchar", "El poema termina así.")],
   [E(f"Lee: «{VIENTO}» ¿Qué verso es una personificación: «silbando una canción» o «en la plaza»?", "«silbando una canción»", "Silbar una canción es una acción humana."),
    E(f"Lee: «{VIENTO}» ¿Cuál es la comparación: «como mariposas» o «cansado»?", "«como mariposas»", "Usa «como» para comparar."),
    E("¿Qué parte de una interpretación muestra por qué pienso eso: la evidencia o la cantidad de versos?", "La evidencia", "Es el verso que apoya la idea.")],
   [E(f"Lee: «{VIENTO}» ¿Qué hacen las hojas: bailan o duermen?", "Bailan", "El poema dice que bailaron alrededor."),
    E(f"Lee: «{VIENTO}» Una persona interpreta «El viento hace que todo se mueva». ¿Qué verso la apoya?", "«Las hojas, como mariposas, bailaron alrededor»", "Muestra el movimiento que provoca el viento."),
    E(f"Lee: «{VIENTO}» ¿Dónde ocurre la escena?", "En la plaza", "El primer verso lo indica.")],
   [E("Alguien dice «El poema muestra una guerra». ¿Se apoya en el poema?", "No", "Los versos hablan de una canción y de hojas que bailan."),
    E("Dos interpretaciones: (a) «Muestra un día de viento como una fiesta» y (b) «Muestra un día de viento. Me gustó». ¿Cuál se apoya mejor?", "(a)", "Explica qué quiere mostrar el poema.")],
   [E(f"Lee: «{VIENTO}» Con la comparación «como mariposas», ¿qué tienen en común las hojas y las mariposas: se mueven livianas por el aire o viven en el agua?", "Se mueven livianas por el aire", "Las hojas que bailan con el viento se parecen a mariposas que vuelan."),
    E("Completa con una evidencia: «El poema muestra tranquilidad al final porque…» (elige: el árbol se quedó quieto a escuchar o las hojas bailaron).", "El árbol se quedó quieto a escuchar", "Quedarse quieto y escuchar muestra calma.")]),
  [E("Lees un poema que dice «La noche se puso su abrigo de estrellas». ¿Qué figura es: personificación o comparación?", "Personificación", "La noche se pone un abrigo como una persona.")],
  [E("¿Qué es interpretar un poema?", "Explicar qué quiere mostrar", "Se hace con apoyo en los versos."),
   E("¿Qué debe acompañar a una interpretación: una evidencia o una opinión sin razón?", "Una evidencia", "Los versos son la prueba."),
   E("¿Dos personas pueden interpretar distinto un mismo poema?", "Sí, si se apoyan en el texto", "Lo importante es la evidencia.")],
  (f"Lee el poema del viento: «{VIENTO}» Escribe una interpretación completa de tres oraciones: 1) qué creo que muestra el poema; 2) un verso que lo apoya; 3) por qué ese verso lo muestra. Subraya la comparación y la personificación que usaste.", "1) El poema muestra un día de viento como una fiesta. 2) «Las hojas, como mariposas, bailaron alrededor». 3) Porque las hojas bailan y parecen mariposas alegres.", ["dice qué muestra el poema", "cita un verso", "explica por qué ese verso lo muestra", "reconoce figuras"], ["tres oraciones", "subrayado"], ["interpretar sin citar", "describir sin explicar"], "Pide a otra persona que lea tu interpretación y diga qué verso necesita para creerla."),
  "Vuelve a leer uno de los poemas de esta semana y explica qué quiere mostrar con un verso.",
  "Escribe un poema de cuatro versos con una comparación y una personificación e interprétalo.")

# ------------------------------------------------------------------ OA 06
CARTA = "Querida Rosa: Te escribo para invitarte a mi cumpleaños. Será el sábado a las cuatro de la tarde, en mi casa. Un abrazo, Camilo."
INSTR = ("Cómo hacer germinar un poroto. Materiales: un vaso plástico, algodón, un poroto y agua. "
         "1. Moja el algodón. 2. Pon el poroto sobre el algodón, dentro del vaso. 3. Deja el vaso cerca de una ventana. 4. Agrega un poco de agua cada día.")
NOTICIA = ("Feria del libro en el gimnasio. La escuela del barrio realizó el viernes por la tarde una feria del libro. "
           "Hubo cuentacuentos, intercambio de libros y juegos de palabras. La entrada fue gratuita.")
BIOGRAFIA = ("Gabriela Mistral nació en Vicuña, Chile, en 1889. Fue maestra y poeta. En 1945 recibió el Premio Nobel de Literatura. Murió en 1957.")
RELATO = ("El 18 de septiembre de 1810 se formó en Santiago la Primera Junta de Gobierno. Con ella, Chile empezó un camino que llevó a su independencia.")
ARTICULO = ("Las abejas producen miel con el néctar de las flores. Viven en colmenas, donde cada abeja tiene un trabajo: unas cuidan a las crías y otras salen a buscar néctar.")

L(OA6, 1,
  "Este cuaderno, lápiz y los textos escritos en esta clase.",
  "Aprenderé a reconocer para qué se escribió un texto no literario (propósito) y a identificar su formato: carta, instrucciones, noticia, artículo informativo, biografía o relato histórico.",
  ["Sé leer textos cortos.", "Distingo un cuento de un texto que informa."],
  ["Los textos no literarios no cuentan historias inventadas. Sirven para comunicar algo real: avisar, enseñar, informar o pedir. Cada uno se escribe para un propósito y tiene un formato que ayuda a reconocerlo.",
   "Una carta comunica un mensaje a una persona. Empieza con un saludo («Querida Rosa:») y termina con una despedida («Un abrazo»). Las instrucciones enseñan a hacer algo y llevan materiales y pasos numerados. Una noticia informa sobre un hecho reciente y empieza con un titular. Un artículo informativo explica un tema con datos.",
   "Para descubrir el propósito, pregúntate: ¿para qué se escribió esto?, ¿cómo está organizado? Si ves pasos numerados, probablemente es una instrucción. Si hay saludo y despedida, es una carta.",
   "Otros dos textos informan sobre el pasado. La biografía cuenta la vida de una persona real: cuándo y dónde nació, qué hizo y qué logró. El relato histórico cuenta un hecho importante del pasado: qué pasó, cuándo y dónde. Los dos se pueden comprobar en libros y no son cuentos inventados."],
  [("propósito", "para qué se escribió un texto"), ("formato", "la forma en que está organizado un texto"), ("noticia", "texto que cuenta un hecho reciente"), ("instrucciones", "texto que enseña a hacer algo paso a paso"), ("biografía", "texto que cuenta la vida de una persona real"), ("relato histórico", "texto que cuenta un hecho importante del pasado")],
  [("Reconocer una carta", f"Lee: «{CARTA}» ¿Qué tipo de texto es y para qué sirve?", ["Tiene saludo: «Querida Rosa».", "Tiene despedida: «Un abrazo».", "Es una carta y sirve para invitar."], "Una carta que invita a un cumpleaños"),
   ("Reconocer instrucciones", f"Lee: «{INSTR}» ¿Qué tipo de texto es?", ["Veo una lista de materiales.", "Hay pasos numerados.", "Es un texto de instrucciones."], "Instrucciones")],
  [("Confundir una noticia con un cuento.", "Ambos cuentan algo.", "Pregunta si es un hecho real y si tiene titular."), ("Pensar que todo texto con pasos es una receta de cocina.", "Se mira solo el contenido.", "Pregunta qué se quiere enseñar a hacer.")],
  ([E(f"Lee: «{CARTA}» ¿A quién va dirigida la carta?", "A Rosa", "El saludo dice «Querida Rosa»."),
    E(f"Lee: «{CARTA}» ¿Quién la escribió?", "Camilo", "Firma al final."),
    E(f"Lee: «{INSTR}» ¿Cuántos pasos numerados tiene?", "4", "Los pasos van del 1 al 4.")],
   [E("¿Cuál es el propósito de una invitación: informar un hecho reciente o invitar a un evento?", "Invitar a un evento", "Pide a alguien que asista."),
    E(f"Lee: «{NOTICIA}» ¿Qué tipo de texto es?", "Una noticia", "Informa un hecho reciente de la comunidad y tiene titular."),
    E(f"Lee: «{ARTICULO}» ¿Qué tipo de texto es: informativo o carta?", "Informativo", "Explica un tema con datos.")],
   [E(f"Lee: «{NOTICIA}» ¿Cuándo se realizó la feria?", "El viernes por la tarde", "Lo dice la segunda oración."),
    E(f"Lee: «{CARTA}» ¿A qué hora será el cumpleaños?", "A las cuatro de la tarde", "La carta dice el día y la hora."),
    E(f"Lee: «{INSTR}» ¿Qué se necesita para el tercer paso: una ventana o una linterna?", "Una ventana", "Hay que dejar el vaso cerca de una ventana.")],
   [E(f"Lee: «{BIOGRAFIA}» ¿Es una biografía o una noticia? Fíjate en lo que cuenta.", "Una biografía", "Cuenta la vida de una persona real: dónde nació, qué hizo y qué premio recibió."),
    E("Un texto tiene una lista de materiales y pasos 1, 2, 3 y 4. ¿Qué propósito tiene: informar de una noticia o enseñar a hacer algo?", "Enseñar a hacer algo", "Las instrucciones guían una tarea.")],
   [E(f"Lee: «{RELATO}» ¿Dónde y en qué año ocurrió este hecho del pasado?", "En Santiago, en 1810", "Un relato histórico dice qué pasó, cuándo y dónde."),
    E("Un texto dice: «Ayer se inauguró una nueva biblioteca en el barrio». ¿Es una noticia o un cuento?", "Una noticia", "Cuenta un hecho reciente.")]),
  [E("Quieres decirle a un compañero que se mejore pronto. Escribes «Querido Tomás: Espero que estés mejor. Un abrazo». ¿Qué formato elegiste?", "Una carta", "Tiene saludo y despedida.")],
  [E("En Lenguaje: ¿Qué es el propósito de un texto?", "Para qué se escribió", "Puede ser informar, enseñar o comunicar."),
   E("¿Qué texto lleva pasos numerados?", "Las instrucciones", "Enseñan a hacer algo."),
   E("¿Qué lleva una carta al comienzo y al final?", "Saludo y despedida", "Es parte de su formato.")],
  ("Lee estos tres textos breves y escribe de qué tipo es cada uno y para qué sirve. Texto 1: «Pon el pan en el plato. Unta mantequilla. Cierra el pan con un trozo de queso.» Texto 2: «Estimada profesora: Mañana no podré asistir. Muchas gracias. Pedro». Texto 3: «Ayer se abrió la plaza nueva del barrio. Tiene juegos y árboles».", "Texto 1: instrucciones, enseña a preparar algo. Texto 2: carta, avisa una ausencia. Texto 3: noticia, informa de la plaza nueva.", ["identifica cada formato", "explica el propósito de cada texto"], ["tres respuestas"], ["confundir noticia con carta", "no decir el propósito"], "Pide a otra persona que diga en qué te fijaste para decidir el tipo."),
  "Busca en tu casa un texto no literario (receta, aviso, carta) y di para qué sirve.",
  "Escribe una carta corta de tres líneas con saludo y despedida.")

INDICE = ("Índice — Los mamíferos: página 3. Las aves: página 7. Los reptiles: página 11. Los anfibios: página 14. Glosario: página 18.")
GLOSARIO = ("Glosario — carnívoro: animal que come carne. hábitat: lugar donde vive un animal. herbívoro: animal que come plantas.")

L(OA6, 2,
  "Este cuaderno, lápiz y el índice y glosario escritos en esta clase.",
  "Aprenderé a usar el título, el subtítulo, el índice y el glosario para encontrar información específica en un texto informativo.",
  ["Sé que los libros están organizados.", "Sé buscar números de página."],
  ["Los libros informativos tienen partes que ayudan a encontrar información rápido. El título dice de qué trata todo el texto. Los subtítulos dicen de qué trata cada parte. El índice es una lista de las partes del libro con el número de la página donde empiezan. El glosario explica palabras difíciles.",
   "Si buscas información sobre las aves, no leas todo el libro. Mira el índice, busca «Las aves» y ve a la página que indica. Si no entiendes la palabra «hábitat», búscala en el glosario: te explica que es el lugar donde vive un animal.",
   "Usar estas partes ahorra tiempo y ayuda a entender mejor. Fíjate también que el glosario ordena las palabras alfabéticamente, por ejemplo: carnívoro, hábitat, herbívoro... En los libros reales, la letra inicial te ayuda a encontrar la palabra."],
  [("título", "nombre del texto, que dice de qué trata"), ("subtítulo", "nombre de cada parte de un texto"), ("índice", "lista de partes de un libro con su página"), ("glosario", "lista de palabras difíciles con su significado")],
  [("Buscar en el índice", f"Lee: «{INDICE}» ¿En qué página empieza la parte de los reptiles?", ["Busco «Los reptiles» en el índice.", "Dice página 11.", "Voy a esa página."], "Página 11"),
   ("Buscar en el glosario", f"Lee: «{GLOSARIO}» ¿Qué significa «herbívoro»?", ["Busco la palabra en el glosario.", "Dice animal que come plantas.", "Esa es su definición."], "Animal que come plantas")],
  [("Leer todo el libro para encontrar un dato.", "No se usa el índice.", "Mira el índice y ve a la página que indica."), ("Confundir título con subtítulo.", "Se piensa que son iguales.", "El título es de todo el texto; el subtítulo es de una parte.")],
  ([E(f"Lee: «{INDICE}» ¿En qué página empieza la parte de las aves?", "En la página 7", "El índice lo dice."),
    E(f"Lee: «{INDICE}» ¿Qué parte empieza en la página 14?", "Los anfibios", "El índice lo dice."),
    E(f"Lee: «{GLOSARIO}» ¿Qué significa «hábitat»?", "Lugar donde vive un animal", "El glosario lo define.")],
   [E("¿Qué es un índice: una lista de partes con su página o una explicación de palabras difíciles?", "Una lista de partes con su página", "Eso es el índice."),
    E("¿Qué es un glosario: una lista de palabras difíciles con su significado o una lista de capítulos?", "Una lista de palabras difíciles con su significado", "Eso es el glosario."),
    E("¿Cuál dice de qué trata todo el texto: el título o el subtítulo?", "El título", "El subtítulo es de una parte.")],
   [arith("Según el índice, los mamíferos empiezan en la página 3 y las aves en la 7. ¿Cuántas páginas ocupan los mamíferos?", "7-3", "Se resta la página donde empiezan los mamíferos de la página donde empiezan las aves."),
    E(f"Lee: «{INDICE}» Quieres información sobre sapos (anfibios). ¿A qué página vas?", "A la página 14", "El índice indica esa página."),
    E(f"Lee: «{GLOSARIO}» ¿Qué significa «carnívoro»?", "Animal que come carne", "El glosario lo explica.")],
   [E(f"Lee: «{INDICE}» Para saber qué es un «herbívoro» sin leer todo, ¿a qué parte vas: al glosario o a Los reptiles?", "Al glosario", "El glosario define palabras."),
    E(f"Lee: «{INDICE}» ¿En qué página está el glosario?", "En la página 18", "El índice lo indica.")],
   [arith("Según el índice, los reptiles empiezan en la página 11 y los anfibios en la 14. ¿Cuántas páginas ocupan los reptiles?", "14-11", "Se resta una página inicial de la otra."),
    E("Un libro tiene un capítulo que se titula «Cómo viven las aves». ¿Eso es un título de libro, un subtítulo o una página?", "Un subtítulo", "Nombra una parte.")]),
  [E("Estás haciendo una tarea sobre los anfibios. ¿Qué parte del libro usas para encontrar rápido dónde empiezan: el índice o el glosario?", "El índice", "El índice indica la página de cada parte.")],
  [E("¿Para qué sirve el índice?", "Para encontrar en qué página está cada parte", "Indica las páginas."),
   E("¿Para qué sirve el glosario?", "Para entender palabras difíciles", "El glosario da el significado de cada palabra."),
   E("¿Qué parte nombra cada sección de un texto?", "Los subtítulos", "Ordenan el texto en partes.")],
  (f"Lee: «{INDICE}» «{GLOSARIO}» Responde en tu cuaderno: 1) ¿En qué página buscarías información sobre los reptiles? 2) ¿Qué parte del libro usarías para saber qué es un hábitat? 3) Escribe un título para un libro nuevo que hable de las aves de tu comuna.", "1) Página 11. 2) El glosario. 3) «Las aves que viven en mi comuna».", ["usa el índice", "usa el glosario", "crea un título relacionado"], ["tres respuestas"], ["leer todo el libro", "confundir índice con glosario"], "Comprueba cada respuesta volviendo al índice o al glosario."),
  "Mira el índice de un libro de tu casa y busca una parte interesante.",
  "Escribe un glosario de tres palabras difíciles de un texto que hayas leído.")

L(OA6, 3,
  "Este cuaderno, lápiz y las descripciones de textos con ilustración escritas en esta clase.",
  "Aprenderé a deducir información que el texto no dice, combinando lo que dice el texto con lo que muestra la ilustración.",
  ["Distingo información explícita e implícita.", "Interpreto una imagen."],
  ["Muchos textos llevan ilustraciones, fotos o dibujos. La ilustración no solo adorna: aporta información que el texto a veces no dice. Para entender mejor, hay que leer el texto y mirar la imagen al mismo tiempo.",
   "Por ejemplo, el texto dice «Joaquín salió al patio con su pelota», y la ilustración muestra el patio cubierto de nieve y a Joaquín con bufanda y gorro. El texto no dice que hace frío, pero la imagen sí lo muestra. Si juntas las dos fuentes, puedes inferir que es invierno.",
   "Para inferir bien, escribe lo que dice el texto, lo que muestra la imagen, y la conclusión que sale de unir ambas cosas. Si la conclusión no se apoya en ninguna de las dos, es una invención."],
  [("ilustración", "dibujo o imagen que acompaña un texto"), ("información visual", "lo que muestra la imagen"), ("combinar", "juntar dos cosas para sacar una conclusión"), ("conclusión", "idea a la que llegas con pistas")],
  [("Texto más ilustración", "Texto: «Joaquín salió al patio con su pelota». Ilustración: el patio está cubierto de nieve y Joaquín lleva bufanda, gorro y guantes. ¿Qué estación puede ser?", ["El texto no dice la estación.", "La nieve y la ropa abrigada muestran frío.", "Por eso puedo inferir que es invierno."], "Invierno"),
   ("Otra inferencia", "Texto: «Mateo miró el reloj y corrió». Ilustración: el reloj marca las ocho y la puerta de la escuela se está cerrando. ¿Por qué corrió Mateo?", ["El texto dice que miró el reloj y corrió.", "La imagen muestra que la puerta se cierra.", "Corrió porque llegaba tarde."], "Porque llegaba tarde")],
  [("Responder solo con el texto y olvidar la imagen.", "Se piensa que la imagen es solo adorno.", "Observa la imagen y anota una pista."), ("Inventar una conclusión sin pista en el texto ni en la imagen.", "Se mezcla imaginación con inferencia.", "Pregunta qué parte del texto o de la imagen apoya tu conclusión.")],
  ([E("Texto: «Joaquín salió al patio con su pelota». Ilustración: el patio está cubierto de nieve. ¿Qué cubre el patio?", "Nieve", "La ilustración lo muestra."),
    E("Ilustración: Joaquín lleva bufanda, gorro y guantes. ¿Qué ropa lleva?", "Bufanda, gorro y guantes", "La ilustración la muestra."),
    E("Texto: «Mateo miró el reloj y corrió». ¿Qué hizo Mateo después de mirar el reloj?", "Corrió", "El texto lo dice.")],
   [E("Texto: «Joaquín salió al patio con su pelota». Ilustración: nieve y ropa abrigada. ¿Hace frío o calor?", "Frío", "La nieve y la ropa abrigada lo muestran."),
    E("Texto: «Mateo miró el reloj y corrió». Ilustración: la puerta de la escuela se está cerrando. ¿Qué intenta Mateo?", "Llegar antes de que cierre la puerta", "La puerta que se cierra explica su prisa."),
    E("Texto: «Rosa viajó una semana». Ilustración: una maceta con una planta seca y una regadera vacía. ¿Qué pasó con la planta?", "No fue regada", "La regadera vacía y la planta seca lo sugieren.")],
   [E("Texto: «Ana abrió el paraguas». Ilustración: gotas cayendo y charcos. ¿Qué tiempo hace?", "Llueve", "Las gotas y los charcos lo muestran."),
    E("Texto: «Pedro se puso gorro y bloqueador». Ilustración: un sol grande y el mar. ¿Dónde puede estar Pedro?", "En la playa", "El sol y el mar sugieren la playa."),
    E("Texto: «Lía sonrió al abrir la caja». Ilustración: dentro hay un cachorro de perro. ¿Por qué sonrió?", "Porque le gustó el cachorro", "La imagen muestra qué había en la caja.")],
   [E("Texto: «Mateo miró el reloj y corrió». Ilustración: el reloj marca las ocho. Un niño dice «Mateo corría porque tenía mucha energía». ¿Se apoya en las pistas?", "No", "Las pistas muestran apuro por la hora, no energía."),
    E("Texto: «Rosa viajó una semana». Ilustración: una planta seca. Un niño dice «la planta está seca por falta de agua». ¿Qué pista de la ilustración lo apoya?", "La regadera vacía", "Muestra que no se regó.")],
   [E("Texto: «Joaquín salió al patio con su pelota». ¿Cuántas pistas de la ilustración sirven para inferir que hace frío: nieve, bufanda, gorro y guantes?", "4", "Todas muestran frío."),
    E("Si la ilustración mostrara a Joaquín en pantalón corto y con sol, ¿qué estación inferirías?", "Verano", "El sol y la ropa liviana sugieren calor.")]),
  [E("En un cartel del colegio hay un texto que dice «Hoy venga con ropa de gimnasia» y un dibujo de una pelota y zapatillas. ¿Qué actividad hay hoy?", "Educación física", "La ropa y el dibujo lo sugieren.")],
  [E("¿La ilustración aporta información o solo adorna?", "Aporta información", "Muestra detalles que el texto puede no decir."),
   E("¿De dónde sale una buena inferencia: del texto y la imagen o de la imaginación sola?", "Del texto y la imagen", "Se apoya en pistas."),
   E("¿Qué debes hacer con el texto y la imagen para inferir?", "Combinarlos", "Se unen las pistas.")],
  ("Mira esta escena descrita: Texto: «Camila subió al bus». Ilustración: Camila lleva una mochila, un sombrero y una botella de agua, y el bus pasa frente a un cerro con árboles. Escribe tres pistas y una conclusión sobre lo que hará Camila.", "Pistas: mochila, botella de agua, cerro con árboles. Conclusión: Camila va de paseo al cerro.", ["menciona tres pistas", "conclusión apoyada en las pistas"], ["tres pistas", "una conclusión"], ["inventar datos", "no usar la imagen"], "Pide a otra persona que diga si tu conclusión se apoya en las pistas."),
  "Mira una foto de un libro y escribe una cosa que la imagen muestra y el texto no dice.",
  "Dibuja una ilustración que permita inferir que hace calor sin escribirlo.")

L(OA6, 4,
  "Este cuaderno, lápiz y las señales descritas en esta clase. Puedes dibujarlas con colores.",
  "Aprenderé a interpretar símbolos y pictogramas, es decir, dibujos que dan un mensaje sin usar palabras, como los letreros de seguridad.",
  ["Sé interpretar una ilustración.", "Reconozco colores y formas."],
  ["Un símbolo es un dibujo o signo que representa una idea. Un pictograma es un dibujo simple que da un mensaje, como las señales de una calle o de un edificio. Se entienden rápido, aunque no sepas leer una frase.",
   "Muchas señales usan formas y colores que significan algo. Un círculo rojo con una línea diagonal significa prohibido. Un triángulo amarillo avisa que hay un peligro: precaución. Un círculo azul indica algo obligatorio. Un cuadrado verde muestra una salida o un lugar seguro.",
   "Para interpretar un pictograma, mira primero la forma y el color, luego el dibujo del centro. Por ejemplo, un círculo rojo con una línea diagonal sobre una bicicleta significa «prohibido andar en bicicleta»."],
  [("símbolo", "signo o dibujo que representa una idea"), ("pictograma", "dibujo simple que da un mensaje"), ("prohibido", "que no se puede hacer"), ("precaución", "cuidado ante un posible peligro")],
  [("Interpretar un pictograma", "Un círculo rojo con una línea diagonal sobre una bicicleta. ¿Qué significa?", ["Veo el círculo rojo con línea: prohibido.", "El dibujo es una bicicleta.", "Prohibido andar en bicicleta."], "Prohibido andar en bicicleta"),
   ("Interpretar por color y forma", "Un triángulo amarillo con un signo de exclamación. ¿Qué indica?", ["El triángulo amarillo avisa de un peligro.", "El signo de exclamación llama la atención.", "Indica precaución."], "Precaución")],
  [("Interpretar solo el dibujo y olvidar el color y la forma.", "Se mira una sola parte.", "Observa forma, color y dibujo."), ("Pensar que todos los símbolos significan lo mismo.", "No se revisa el contexto.", "Pregunta dónde está el símbolo y qué muestra.")],
  ([E("¿Qué significa un círculo rojo con una línea diagonal?", "Prohibido", "Es la señal de prohibición."),
    E("¿Qué color tiene un triángulo de precaución?", "Amarillo", "Así se usa en las señales de advertencia."),
    E("¿Qué es un pictograma?", "Un dibujo simple que da un mensaje", "Se entiende sin leer palabras.")],
   [E("Un cuadrado verde con una persona caminando hacia una puerta. ¿Qué indica: peligro o salida?", "Salida", "El verde muestra un lugar seguro o una salida."),
    E("Un círculo rojo con una línea diagonal sobre un perro. ¿Qué indica?", "Prohibido pasar con perros", "La línea diagonal indica prohibición."),
    E("Un círculo azul con una flecha hacia arriba. ¿Qué tipo de mensaje es: prohibición u obligación?", "Obligación", "El círculo azul muestra algo que hay que hacer.")],
   [E("Un triángulo amarillo con una persona resbalando. ¿Qué te avisa?", "Que el piso puede estar resbaloso", "El triángulo amarillo advierte un peligro."),
    E("Un círculo rojo con una línea diagonal sobre una pelota. ¿Qué indica?", "Prohibido jugar a la pelota", "La línea diagonal prohíbe lo que muestra el dibujo."),
    E("Un cuadrado verde con una cruz blanca. ¿Qué lugar crees que indica: un lugar de primeros auxilios o una zona de peligro?", "Un lugar de primeros auxilios", "El verde y la cruz indican un lugar seguro con ayuda.")],
   [E("Un niño ve un círculo rojo con una línea diagonal sobre un teléfono celular y dice «Aquí puedo usar el celular». ¿Entendió bien?", "No", "La señal prohíbe usar el celular."),
    E("¿Por qué las señales usan colores y formas fijos: para que se entiendan rápido o para decorar?", "Para que se entiendan rápido", "Todos reconocen el mensaje de un vistazo.")],
   [E("Lee las señales: círculo rojo con línea, triángulo amarillo, cuadrado verde. ¿Cuántas indican peligro o prohibición?", "2", "El círculo rojo prohíbe y el triángulo amarillo advierte; el verde indica seguridad."),
    E("En una piscina hay una señal con un triángulo amarillo y una persona resbalando. ¿Qué debes hacer: correr o caminar con cuidado?", "Caminar con cuidado", "Es una advertencia por piso resbaloso.")]),
  [E("En la puerta del gimnasio hay un círculo rojo con una línea diagonal sobre una mochila grande. ¿Qué indica?", "Prohibido entrar con mochilas grandes", "La línea diagonal prohíbe lo que muestra el dibujo.")],
  [E("¿Qué indica un triángulo amarillo?", "Precaución", "Advierte un posible peligro."),
   E("¿Qué indica un cuadrado verde?", "Salida o lugar seguro", "El verde muestra seguridad."),
   E("¿Qué indica un círculo rojo con línea diagonal?", "Prohibido", "La línea tacha lo que muestra el dibujo.")],
  ("Diseña en tu cuaderno tres pictogramas para tu sala: uno que prohíba algo (círculo rojo con línea), uno que avise precaución (triángulo amarillo) y uno que indique un lugar seguro (cuadrado verde). Debajo de cada uno escribe qué significa.", "1) Círculo rojo con línea sobre un balón: prohibido jugar a la pelota en la sala. 2) Triángulo amarillo con una persona resbalando: piso mojado. 3) Cuadrado verde con una puerta: salida de la sala.", ["usa las formas y colores correctos", "el dibujo central coincide con el mensaje", "explica el significado"], ["tres pictogramas", "tres explicaciones"], ["usar colores equivocados", "no escribir el significado"], "Muestra tus pictogramas a otra persona y comprueba si entiende el mensaje sin leer."),
  "Observa tres señales en la calle o en tu escuela y anota qué significan.",
  "Inventa un pictograma para pedir silencio en la biblioteca.")

SEMILLA = ("Una semilla guarda dentro una planta pequeña. Para germinar, necesita agua y una temperatura tibia. "
           "Si el suelo está muy seco, la semilla no se hincha y no brota. Por eso los jardineros riegan la tierra después de sembrar.")

L(OA6, 5,
  "Este cuaderno, lápiz y el texto informativo escrito en esta clase.",
  "Aprenderé a relacionar la información que un texto dice con la que debo deducir, para comprender mejor un texto informativo.",
  ["Distingo información explícita e implícita.", "Uso títulos y subtítulos."],
  ["En un texto informativo hay datos explícitos, que se leen directamente, y datos implícitos, que se deducen al unir datos explícitos. Para relacionar ambas, primero subraya lo que dice el texto y luego pregúntate qué otra cosa se puede concluir.",
   "El texto de la semilla dice que necesita agua y temperatura tibia para germinar. También dice que si el suelo está muy seco, no brota. No dice qué pasa si alguien siembra y se olvida de regar. Pero se puede concluir que probablemente no brotará, porque la tierra seguirá seca. Esa conclusión no está escrita: se deduce.",
   "Una conclusión es válida si se apoya en dos o más datos del texto. Un truco útil es completar la frase «Si… entonces…». Si no se riega, entonces el suelo sigue seco; si el suelo sigue seco, entonces la semilla no brota."],
  [("germinar", "empezar a crecer una semilla"), ("brotar", "salir una planta de la semilla"), ("deducir", "sacar una conclusión a partir de datos"), ("relacionar", "unir datos entre sí")],
  [("Relacionar datos", f"Lee: «{SEMILLA}» Una persona siembra semillas y nunca riega la tierra. ¿Brotarán?", ["El texto dice que la semilla necesita agua.", "Si no riega, la tierra seguirá seca, y con suelo seco no brotan.", "Entonces probablemente no brotarán."], "Probablemente no, porque la tierra seguirá seca"),
   ("Explicar una acción", "¿Por qué los jardineros riegan la tierra después de sembrar?", ["Busco la razón en el texto.", "La semilla necesita agua para germinar.", "Por eso riegan."], "Porque las semillas necesitan agua para germinar")],
  [("Responder con una idea que no sale del texto.", "Se usa solo la memoria.", "Localiza en el texto los datos y únelos."), ("Pensar que lo implícito es inventar.", "No se ve la relación.", "Usa «Si… entonces…» con datos del texto.")],
  ([E(f"Lee: «{SEMILLA}» ¿Qué necesita una semilla para germinar?", "Agua y una temperatura tibia", "El texto lo dice."),
    E(f"Lee: «{SEMILLA}» ¿Qué guarda dentro una semilla?", "Una planta pequeña", "Así lo dice la primera oración."),
    E(f"Lee: «{SEMILLA}» ¿Qué hacen los jardineros después de sembrar?", "Riegan la tierra", "El texto lo dice.")],
   [E(f"Lee: «{SEMILLA}» Si el suelo está muy seco, ¿qué pasa con la semilla?", "No se hincha y no brota", "El texto lo dice."),
    E("Completa con «Si… entonces…»: «Si el suelo está seco, entonces la semilla…» (elige: no brota o brota rápido).", "No brota", "El texto dice que sin agua no brota."),
    E(f"Lee: «{SEMILLA}» ¿Es explícito o implícito que «una semilla en tierra seca no brota»?", "Explícito", "El texto lo dice directamente.")],
   [E(f"Lee: «{SEMILLA}» Una semilla está en tierra húmeda y tibia. ¿Qué es probable que pase?", "Que germine", "Tiene agua y temperatura adecuada."),
    E(f"Lee: «{SEMILLA}» Una persona siembra semillas y se olvida de regar. ¿Qué puede ocurrir?", "Que no broten", "Sin agua no germinan."),
    E(f"Lee: «{SEMILLA}» ¿Qué dos condiciones necesita una semilla para germinar?", "Agua y temperatura tibia", "El texto las nombra.")],
   [E(f"Lee: «{SEMILLA}» Alguien dice «Las semillas necesitan música para germinar». ¿Se apoya en el texto?", "No", "El texto no habla de música."),
    E(f"Lee: «{SEMILLA}» Un jardinero sembró y regó, pero la tierra está helada. ¿Qué dato del texto explica que quizá las semillas no germinen?", "Necesitan una temperatura tibia", "El texto dice que la semilla necesita agua y temperatura tibia; con tierra helada falta una de las dos.")],
   [E(f"Lee: «{SEMILLA}» Ordena de la causa a la consecuencia: (a) la semilla no brota, (b) el suelo está muy seco, (c) la semilla no se hincha.", "b, c, a", "El suelo seco hace que no se hinche y por eso no brota."),
    E(f"Lee: «{SEMILLA}» Si una semilla está en tierra seca pero tibia, ¿se cumplen las dos condiciones?", "No", "Falta el agua.")]),
  [E("En tu casa quieres sembrar un poroto. ¿Qué harás para ayudarlo a germinar: regar la tierra o dejarlo sin agua?", "Regar la tierra", "La semilla necesita agua.")],
  [E("¿Qué es deducir?", "Sacar una conclusión a partir de datos", "Se une información del texto."),
   E("¿La información implícita está escrita o se deduce?", "Se deduce", "Hay que unir datos."),
   E("¿Qué frase ayuda a deducir: «Si… entonces…» o «Había una vez…»?", "«Si… entonces…»", "Une una condición con una conclusión.")],
  (f"Lee el texto: «{SEMILLA}» Completa tres frases en tu cuaderno: 1) «Un dato explícito es…» 2) «Si no se riega la tierra, entonces…» 3) «Un dato que NO sabemos con este texto es…»", "1) Que la semilla necesita agua y temperatura tibia. 2) La semilla no brota. 3) Cuántos días tarda en germinar.", ["dato explícito correcto", "conclusión con «Si… entonces…»", "reconoce algo que el texto no dice"], ["tres frases completas"], ["inventar un dato", "no apoyar la conclusión"], "Subraya en el texto el dato que apoya tu conclusión."),
  "Lee un párrafo informativo y escribe una conclusión con «Si… entonces…».",
  "Escribe un texto de tres oraciones sobre el sol y las plantas y una conclusión que se pueda deducir.")

BICI = ("Ir a la escuela en bicicleta. Muchos niños van a la escuela en bicicleta con casco. Así hacen ejercicio y no usan auto, por lo que hay menos humo. "
        "Pero deben cruzar con cuidado y usar ciclovías cuando las hay.")

L(OA6, 6,
  "Este cuaderno, lápiz y el texto escrito en esta clase.",
  "Aprenderé a formarme una opinión sobre lo que leo en un texto no literario y a respaldarla con información del texto o con lo que ya sé.",
  ["Distingo datos y opiniones.", "Relaciono información explícita e implícita."],
  ["Un dato es algo que se puede comprobar. «Muchos niños van en bicicleta» es un dato. Una opinión es lo que alguien piensa, como «Ir en bicicleta es lo mejor». Cuando lees un texto informativo, puedes formarte una opinión sobre lo que dice.",
   "Para que tu opinión tenga respaldo, debes dar una razón basada en el texto o en lo que sabes. Por ejemplo: «Creo que ir en bicicleta es buena idea porque se hace ejercicio y hay menos humo». El texto dice esas dos razones.",
   "También puedes pensar en lo que el texto advierte. «Pero deben cruzar con cuidado» es un dato que muestra que no todo es perfecto. Una opinión bien formada considera lo bueno y lo que hay que cuidar."],
  [("dato", "información que se puede comprobar"), ("opinión", "lo que alguien piensa sobre algo"), ("respaldo", "razón o dato que apoya una opinión"), ("ciclovía", "camino especial para bicicletas")],
  [("Opinión con respaldo", f"Lee: «{BICI}» ¿Cuál opinión tiene respaldo: «Ir en bicicleta es buena idea porque se hace ejercicio» o «Ir en bicicleta es buena idea»?", ["La primera dice porque.", "La razón sale del texto.", "La primera tiene respaldo."], "La primera"),
   ("Distinguir dato y opinión", "«Muchos niños van a la escuela en bicicleta.» ¿Es dato u opinión?", ["Se puede comprobar contando.", "No expresa lo que alguien piensa.", "Es un dato."], "Es un dato")],
  [("Decir lo que piensas sin dar ninguna razón.", "Se cree que basta opinar.", "Agrega «porque» y un dato del texto."), ("Confundir un dato con una opinión.", "No se revisa si se puede comprobar.", "Pregunta ¿esto se puede comprobar?")],
  ([E(f"Lee: «{BICI}» ¿Qué usan los niños para ir en bicicleta?", "Casco", "El texto dice que van con casco."),
    E(f"Lee: «{BICI}» ¿Qué tienen que hacer los niños al cruzar?", "Cruzar con cuidado", "Así lo dice el texto."),
    E(f"Lee: «{BICI}» ¿Qué hay menos cuando se usa menos el auto?", "Humo", "El texto lo dice.")],
   [E("«Ir en bicicleta es aburrido.» ¿Es dato u opinión?", "Opinión", "Expresa lo que alguien piensa."),
    E("«Los niños usan casco.» ¿Es dato u opinión?", "Dato", "Se puede comprobar."),
    E("¿Qué hace que una opinión tenga respaldo: una razón o gritar más fuerte?", "Una razón", "La razón la sostiene.")],
   [E(f"Lee: «{BICI}» Elige la opinión con respaldo: (a) «Es buena idea porque se hace ejercicio y hay menos humo» o (b) «Es mala idea porque sí».", "(a)", "Da razones que salen del texto."),
    E(f"Lee: «{BICI}» ¿Qué razón del texto apoya la opinión «Ir en bicicleta cuida el aire»?", "Que hay menos humo", "El texto dice que hay menos humo."),
    E(f"Lee: «{BICI}» ¿Qué razón del texto apoya la opinión «Ir en bicicleta es sano»?", "Que se hace ejercicio", "El texto lo dice.")],
   [E("Un niño dice «No me gusta la bicicleta, así que es mala idea». ¿Su opinión tiene respaldo del texto?", "No", "No usa ningún dato del texto."),
    E(f"Lee: «{BICI}» Otra niña opina «Es buena idea, pero hay que cruzar con cuidado». ¿Considera lo que advierte el texto?", "Sí", "Nombra la advertencia del texto.")],
   [E(f"Lee: «{BICI}» Alguien dice «Los niños que van en bicicleta sacan mejores notas». ¿Tiene respaldo en el texto?", "No", "El texto habla de ejercicio, humo y cuidado al cruzar, no de notas."),
    E(f"Lee: «{BICI}» ¿Qué dato del texto muestra que hay que ser prudente: el casco, las ciclovías o ambos?", "Ambos", "Los dos son medidas de seguridad.")]),
  [E("Tu escuela decide si organiza una jornada para ir en bicicleta. Quieres opinar. ¿Qué respuesta es mejor: «Me parece buena idea porque ayuda a hacer ejercicio» o «Me parece buena idea»?", "«Me parece buena idea porque ayuda a hacer ejercicio»", "Da una razón.")],
  [E("En Lenguaje: ¿Un dato se puede comprobar?", "Sí", "Se puede verificar."),
   E("¿Qué necesita una opinión para tener respaldo?", "Una razón", "La razón sale del texto o de lo que sé."),
   E("¿De dónde puede salir el respaldo de una opinión?", "Del texto o de mis conocimientos", "Ambos son válidos.")],
  (f"Lee el texto: «{BICI}» Escribe una opinión de tres oraciones: 1) lo que piensas; 2) una razón del texto; 3) algo que sabes tú o una precaución que agregarías.", "Creo que es buena idea ir en bicicleta, porque se hace ejercicio. También hay menos humo. Yo agregaría que hay que usar siempre casco.", ["expresa una opinión", "da una razón del texto", "agrega un conocimiento o precaución"], ["tres oraciones"], ["opinar sin razón", "inventar datos"], "Pide a otra persona que subraye la razón en tu opinión."),
  "Lee una noticia corta y escribe una opinión con una razón.",
  "Escribe una opinión sobre el reciclaje con dos razones.")
